import{_ as o,o as t,c as a,a0 as n}from"./chunks/framework.ZNXClGez.js";const p=JSON.parse('{"title":"Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/upgrading.md","filePath":"guide/deployment/upgrading.md"}'),i={name:"guide/deployment/upgrading.md"};function r(s,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><p>This page collects <strong>action-required</strong> notes for upgrading an existing deployment. Entries are grouped by release, newest first. Routine changes (features, fixes) live in the <a href="https://github.com/authup/authup/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a>; anything listed here either requires operator action or deliberately changes behavior.</p><h2 id="next-release-after-v1-0-0-beta-62" tabindex="-1">Next release (after v1.0.0-beta.62) <a class="header-anchor" href="#next-release-after-v1-0-0-beta-62" aria-label="Permalink to &quot;Next release (after v1.0.0-beta.62)&quot;">​</a></h2><h3 id="authup-is-the-only-binary-and-it-runs-the-server-in-process" tabindex="-1"><code>authup</code> is the only binary, and it runs the server in process <a class="header-anchor" href="#authup-is-the-only-binary-and-it-runs-the-server-in-process" aria-label="Permalink to &quot;`authup` is the only binary, and it runs the server in process&quot;">​</a></h3><p>The <code>authup-server</code> binary is retired. The <code>@authup/server-core</code> package ships no binary at all now; the <code>authup</code> package (<code>npm install authup</code>) carries the one command and runs the server <strong>inside its own process</strong>, where it used to start it as a child and supervise it.</p><table tabindex="0"><thead><tr><th>Was</th><th>Is</th></tr></thead><tbody><tr><td><code>authup-server start</code></td><td><code>authup start</code></td></tr><tr><td><code>authup-server worker</code></td><td><code>authup worker</code></td></tr><tr><td><code>authup-server migration run</code></td><td><code>authup migration run</code></td></tr><tr><td><code>authup-server healthcheck</code></td><td><code>authup healthcheck</code></td></tr></tbody></table><p><strong>Containers need no change.</strong> The entrypoint vocabulary is unchanged: <code>server/core start</code>, <code>server/core worker</code> and <code>server/core migration run</code> all still work, and the image runs the <code>authup</code> CLI underneath. A Compose file, a Helm values file or a <code>docker run</code> line that names <code>server/core &lt;command&gt;</code> is already correct.</p><p><strong>Action required</strong> for anything that invoked the binary by name: a systemd unit, a PM2 config, a Procfile, a CI step or an <code>npm</code> script naming <code>authup-server</code>. Install the <code>authup</code> package and use the commands in the table. <code>authup worker</code> is new on this path: the worker role was previously reachable through the <code>authup-server</code> binary only, and the CLI could not start it.</p><p><strong><code>PORT</code> and <code>HOST</code> now follow the normal precedence.</strong> The supervisor always forced them onto the child, taking the value from the <code>server.core</code> section of the configuration file (or the defaults) and overriding whatever the environment said. They are ordinary options again, so the <a href="./configuration.html#layers-precedence">layering</a> applies: an environment variable beats the configuration file. That is what a PaaS injecting <code>PORT</code> expects, and it is what every other option already did.</p><p><strong>Action required</strong> for a deployment that set <code>PORT</code> or <code>HOST</code> in the environment while ALSO naming <code>server.core.port</code> / <code>server.core.host</code> in the configuration file, and relied on the file winning. The two now disagree in the other direction. Drop one of them.</p><p><strong>Package selectors are gone.</strong> <code>authup start server.core</code> and <code>authup start client.admin-console</code> are refused as an unexpected argument; <code>start</code> and <code>worker</code> take no positional argument, because the CLI starts exactly one service. A <code>client.admin-console</code> section in the configuration file is not read (it printed a deprecation warning before). Remove both.</p><p>Two smaller things need no action. <code>authup migration run</code> finds its migration files wherever it is started from, so on a normal install the working directory no longer has to be the installed server package. And signal handling reaches the server directly instead of being forwarded: <code>SIGINT</code>/<code>SIGTERM</code> tear the application down and exit with its outcome, a second signal exits immediately, and a teardown outlasting 10 seconds is forced.</p><h3 id="the-consoles-moved-under-console" tabindex="-1">The consoles moved under <code>/console</code> <a class="header-anchor" href="#the-consoles-moved-under-console" aria-label="Permalink to &quot;The consoles moved under `/console`&quot;">​</a></h3><p>Every console <code>server-core</code> serves now lives under one <code>/console</code> prefix on the IdP origin:</p><table tabindex="0"><thead><tr><th>Surface</th><th>Was</th><th>Is</th></tr></thead><tbody><tr><td>Admin console</td><td><code>&lt;publicUrl&gt;/admin</code> (unreleased, see the next entry)</td><td><code>&lt;publicUrl&gt;/console/admin</code></td></tr><tr><td>Account console</td><td><code>&lt;publicUrl&gt;/account</code></td><td><code>&lt;publicUrl&gt;/console/account</code></td></tr><tr><td>Auth console assets (the scripts and styles behind <code>/authorize</code>, <code>/logout</code>, <code>/register</code>, ...)</td><td><code>&lt;publicUrl&gt;/public/</code></td><td><code>&lt;publicUrl&gt;/console/auth/assets/</code></td></tr></tbody></table><p>The auth pages themselves (<code>/authorize</code>, <code>/logout</code>, <code>/register</code>, <code>/activate</code>, <code>/password-forgot</code>, <code>/password-reset</code>) and every API route are unchanged. They are the protocol surface (<code>authorization_endpoint</code>, <code>end_session_endpoint</code>, the mail deep links) and stay at the root. <code>/console</code> and <code>/console/auth</code> themselves serve nothing.</p><p><strong>Action required.</strong></p><ul><li><strong>Rebuild and redeploy every console together with the server.</strong> The base path is baked into each bundle&#39;s <code>index.html</code>, and the server mounts the assets under the new path only. A <code>@authup/client-admin-console</code> or <code>@authup/client-account-console</code> dist built for the old base is served without any error and renders a blank console: the shell keeps its old <code>src=&quot;/admin/assets/...&quot;</code> hrefs, which nothing answers any more. The published packages and the Docker image of this release carry matching bundles; a package you substitute (<code>ADMIN_CONSOLE_PATH</code>, <code>ACCOUNT_CONSOLE_PATH</code>, <code>AUTH_CONSOLE_PATH</code>) has to be rebuilt with the new vite base (<code>/console/admin/</code>, <code>/console/account/</code>, <code>/console/auth/</code>).</li><li><strong>Links, bookmarks and proxy rules</strong> naming <code>/account</code>, <code>/admin</code> or <code>/public</code> must name the new paths. That includes the sign-in routes (<code>/console/account/login</code>, <code>/console/account/callback</code> and the admin pair) and every page below a console (<code>/console/account/authenticators</code>, ...). Update the &quot;Manage account&quot; link your own applications render.</li><li><strong>No redirect is served for the old paths.</strong> <code>/account/**</code>, <code>/admin/**</code> and <code>/public/**</code> answer <code>404</code>.</li><li><strong><code>@authup/client-web-kit</code> and the server must be on the same release.</strong> The kit&#39;s <code>buildConsoleLoginURL</code> now emits <code>&lt;baseURL&gt;/console/&lt;console&gt;/login</code>. A newer kit against an older server kicks to a route that does not exist, and an older kit (or an older standalone-hosted console bundle) against this server does the same the other way round; a <code>404</code> on a top-level navigation is unrecoverable.</li><li><strong>Standalone hosting</strong>: the default <code>basePath</code> a console assumes is now <code>/console/admin</code> and <code>/console/account</code>. A host may serve the bundle under any other base by injecting <code>basePath</code> (see <a href="./configuration-client-admin-console.html#standalone-hosting">Admin Console</a> and <a href="./account-console.html#standalone-hosting">Account Console</a>); the same-origin API derivation strips the full two-segment default.</li></ul><p>One prefix is what makes serving the consoles from their own replica set a single proxy rule; see <a href="./console-replicas.html">Console Replicas</a>.</p><p>Also in this release, <code>ACCOUNT_CONSOLE_ENABLED=false</code> applies to the account console&#39;s sign-in routes as well: <code>GET /console/account/login</code> and <code>GET /console/account/callback</code> answer the &quot;not enabled&quot; notice instead of starting a login, the way the admin console&#39;s routes did already. Before, a disabled account console still minted a pending login and a session cookie on a direct hit. No action needed.</p><h3 id="the-admin-console-is-served-by-server-core" tabindex="-1">The admin console is served by server-core <a class="header-anchor" href="#the-admin-console-is-served-by-server-core" aria-label="Permalink to &quot;The admin console is served by server-core&quot;">​</a></h3><p>The admin console is no longer a separate Nuxt server. It is a static single-page bundle that <code>server-core</code> serves at <code>&lt;publicUrl&gt;/console/admin</code>, the way it serves the account console at <code>&lt;publicUrl&gt;/console/account</code> (the <code>/console</code> prefix is the entry above). A deployment runs one process.</p><p><strong>Action required.</strong></p><ul><li><strong>Docker / Compose</strong>: remove the <code>client/admin-console</code> service. The entrypoint no longer starts it: <code>client/admin-console start</code> prints the replacement and exits <code>1</code>, so a stale service fails loudly instead of reporting a healthy run having started nothing. The remaining <code>server/core</code> container serves the console.</li><li><strong>Helm</strong>: the chart in the <code>authup/helm</code> repository still deploys an admin console workload, whose pods now crash-loop for the reason above. Remove or scale that workload to zero. A follow-up chart release drops it.</li><li><strong>Bare metal</strong>: the command does not change. <code>authup start</code> starts <code>server/core</code> alone. <code>authup start client.admin-console</code> is refused and a <code>client.admin-console</code> section in <code>authup.conf</code> is not read (see the entry above). Remove both.</li><li><strong><code>TRUSTED_ORIGINS</code></strong>: drop the console&#39;s former origin. It serves nothing now, but the provisioner keeps re-asserting every listed origin into the system clients&#39; redirect allowlists on each boot.</li><li><strong>Reverse proxy</strong>: collapse the two upstreams into one. The API and both consoles are served by the same listener, so a rule that routed <code>/</code> to the console port and <code>/api/</code> to the server port routes <code>/</code> to the server port now. See <a href="./nginx.html">Nginx</a>.</li><li><strong>Links and bookmarks</strong>: the console moved from the root of its own origin to <code>&lt;publicUrl&gt;/console/admin</code>.</li></ul><p><strong>Retired environment variables</strong>, none with a successor: <code>NUXT_PUBLIC_API_URL</code>, <code>NUXT_PUBLIC_PUBLIC_URL</code>, <code>NUXT_PUBLIC_COOKIE_DOMAIN</code>, <code>NUXT_PUBLIC_CLIENT_ID</code>, <code>NUXT_HOST</code>, <code>NUXT_PORT</code>, and the console&#39;s build-time names <code>API_URL</code>, <code>API_URL_SERVER</code>, <code>PUBLIC_URL</code>, <code>COOKIE_DOMAIN</code> and <code>CLIENT_ID</code>. The cookie domain is moot: the console is same-origin with the API, so there is nothing to widen. Note that <code>PUBLIC_URL</code> is unaffected as a <a href="./configuration-server-core.html"><code>server/core</code> option</a>; it is the server&#39;s own public URL, and the console&#39;s address derives from it.</p><p><strong>New <code>server/core</code> options.</strong> <code>ADMIN_CONSOLE_ENABLED</code> / <code>adminConsoleEnabled</code> (default <code>true</code>) serves the console; with it off the routes render a &quot;not enabled&quot; notice (and the sign-in routes start no login), so stale links do not dead-end. <code>ADMIN_CONSOLE_PATH</code> / <code>adminConsolePath</code> substitutes the console package, the same contract as <code>ACCOUNT_CONSOLE_PATH</code>: a directory holding a built <code>dist/</code> whose <code>index.html</code> carries the <code>&lt;!--admin-config--&gt;</code> marker. The <code>features</code> block of the public status endpoint (<code>GET /</code>) gains <code>adminConsole</code>.</p><p><strong>Deliberately gone</strong>: the <code>authup-admin-console</code> binary and the published Nuxt server bundle. <code>@authup/client-admin-console</code> ships <code>dist/</code> only. The bundle stays hostable on a static host of your own, on its own origin; see <a href="./configuration-client-admin-console.html#standalone-hosting">Admin Console</a>.</p><p>Sign-in changed as well and needs no action. Served from the API&#39;s origin, the console authenticates with the same opaque <code>HttpOnly</code> session cookie the account console uses (<code>GET /console/admin/login</code> and <code>GET /console/admin/callback</code> against the per-realm <code>admin-console</code> client), so no OAuth2 token reaches the browser&#39;s JavaScript. Hosted standalone on a foreign origin it keeps the browser-side authorization-code flow with PKCE.</p><h3 id="token-introspection-requires-authorization" tabindex="-1">Token introspection requires authorization <a class="header-anchor" href="#token-introspection-requires-authorization" aria-label="Permalink to &quot;Token introspection requires authorization&quot;">​</a></h3><p><code>POST /token/introspect</code> (and its <code>GET</code> form) now answers <code>401</code> to a request carrying no credentials, as RFC 7662 section 2.1 requires (&quot;the endpoint MUST also require some form of authorization&quot;). Two forms are accepted:</p><ul><li>a <strong>live bearer</strong>: <code>Authorization: Bearer &lt;access token&gt;</code>. The token may be the one being introspected (what <code>@authup/client-web-kit</code> sends) or the caller&#39;s own, for instance a resource server&#39;s client-credentials token (what the <code>@authup/server-adapter-*</code> packages send, minted on the first <code>401</code> and replayed);</li><li><strong>confidential client credentials</strong>: <code>client_id</code> + <code>client_secret</code> in the form body or as <code>Authorization: Basic</code>, or a <code>tls</code> client&#39;s certificate. A public client (<code>authMethod: none</code>) is refused with <code>invalid_client</code>; its bare <code>client_id</code> identifies it but proves nothing.</li></ul><p>Authentication is the first layer. The second is WHOSE tokens the caller may introspect: the caller&#39;s own (the subject matches), tokens issued for the caller&#39;s own client (the token&#39;s <code>client_id</code>), or any token reached by the new <code>token_introspect</code> permission (realm-scoped: an <code>admin</code> reaches everything, a default grant covers the client&#39;s own realm). A caller failing all three receives a bare <code>{&quot;active&quot;: false}</code>, as RFC 7662 section 2.2 prescribes for a resource &quot;not allowed to introspect&quot;. The server logs the denial, since the response is indistinguishable from a dead token by design.</p><p><strong>Action required for resource servers</strong> using <code>@authup/server-adapter-*</code> remote verification: grant <code>token_introspect</code> to the client behind the verifier&#39;s <code>creator</code>, or foreign tokens will verify as inactive. A downstream application introspecting tokens issued to its own client needs no grant.</p><p>The expired-token report (next section) is gated the same way: it is reachable only by a caller that proved who it is and may introspect that token. An expired token is NOT a credential: the authorization middleware rejects an expired bearer before the endpoint runs, so a request whose only token is the lapsed one answers <code>401</code>.</p><p><strong>Action required</strong> for an integration that called the endpoint anonymously: send one of the two credentials. Nothing changes for <code>@authup/client-web-kit</code> (it introspects its own token). For the <code>@authup/server-adapter-*</code> packages the credential replay flow is preserved, but verifying foreign tokens now additionally requires the <code>token_introspect</code> grant described above. <code>POST /token/revoke</code> stays open as a deliberate authup choice: RFC 7009 asks a public client to identify itself by <code>client_id</code> and the server to verify token ownership, but a public <code>client_id</code> proves nothing, and possession of the token already lets its holder use it. Revoking is the benign action.</p><h3 id="introspecting-an-expired-token-now-returns-its-payload" tabindex="-1">Introspecting an expired token now returns its payload <a class="header-anchor" href="#introspecting-an-expired-token-now-returns-its-payload" aria-label="Permalink to &quot;Introspecting an expired token now returns its payload&quot;">​</a></h3><p><code>POST /token/introspect</code> answers <code>200</code> with <code>&quot;active&quot;: false</code> <strong>and the token&#39;s payload and subject claims</strong> for an expired token, where it previously raised <code>401</code>. A relying party can now tell the person whose session ended who they were - &quot;your session expired, Alice&quot; - instead of only that something failed.</p><p>A token the server cannot read at all - malformed, a bad signature, a <code>kid</code> naming no known key - is also reported now, as a bare <code>{&quot;active&quot;: false}</code>. It answered <code>401</code> (or <code>404</code>) before. RFC 7662 section 2.2 requires this: a token that &quot;does not exist on this server&quot; is reported, not raised. A missing <code>token</code><strong>parameter</strong> is still a malformed request and still answers <code>400</code>.</p><p><strong><code>permissions</code> is no longer returned for an inactive token</strong>, expired ones included. It names who the token belonged to, not what they were allowed to do. A caller that read <code>permissions</code> off an introspection response must check <code>active</code> first - which it should have been doing regardless.</p><h3 id="token-revocation-answers-200-and-answers-it-for-invalid-tokens-too" tabindex="-1">Token revocation answers 200, and answers it for invalid tokens too <a class="header-anchor" href="#token-revocation-answers-200-and-answers-it-for-invalid-tokens-too" aria-label="Permalink to &quot;Token revocation answers 200, and answers it for invalid tokens too&quot;">​</a></h3><p><code>POST /token/revoke</code> returned <code>202</code>. It now returns <strong><code>200</code></strong>, the status RFC 7009 section 2.2 names. Both are 2xx, so a client checking the status class is unaffected; a client comparing against <code>202</code> exactly is not.</p><p>The same <code>200</code> is now returned for a malformed or unverifiable token, per the same section - &quot;invalid tokens do not cause an error response since the client cannot handle such an error in a reasonable way&quot;. Expired tokens already behaved this way. The point of the rule is that an invalid token is indistinguishable from a revoked one, so do not expect to detect a bad token from the response.</p><p><strong>Action required if you branch on the failure.</strong> A client that treated a <code>401</code> from introspection as &quot;the token is dead&quot; now has to read <code>active</code>, which is the field RFC 7662 defines for it.</p><p><code>@authup/client-web-kit</code> is updated in step: its store refuses to commit a session for a response reporting <code>active: false</code>, which it previously ignored - so a revoked or expired token restored from cookies rendered as authenticated until the next protected request failed. Upgrade the kit alongside the server.</p><h3 id="a-bearer-token-whose-key-is-unknown-answers-401-not-404" tabindex="-1">A bearer token whose key is unknown answers 401, not 404 <a class="header-anchor" href="#a-bearer-token-whose-key-is-unknown-answers-401-not-404" aria-label="Permalink to &quot;A bearer token whose key is unknown answers 401, not 404&quot;">​</a></h3><p>An access token whose <code>kid</code> names no key, an encryption key, or a disabled key was reported as <code>404 jwk_not_found</code> on every route. It is now <code>401</code> with the <code>invalid_token</code> code, which is what a resource server expects from a credential it cannot verify. The practical effect is that clients recover from a key rotation instead of treating it as a missing resource.</p><h3 id="_401-responses-from-protected-routes-carry-www-authenticate" tabindex="-1">401 responses from protected routes carry <code>WWW-Authenticate</code> <a class="header-anchor" href="#_401-responses-from-protected-routes-carry-www-authenticate" aria-label="Permalink to &quot;401 responses from protected routes carry `WWW-Authenticate`&quot;">​</a></h3><p>Per RFC 6750 section 3, a <code>401</code> from a protected resource now carries <code>WWW-Authenticate: Bearer error=&quot;invalid_token&quot;, error_description=&quot;...&quot;</code>, or a bare <code>Bearer</code> when the request presented no credentials at all. The token endpoint&#39;s own <code>401</code> (<code>invalid_client</code>, RFC 6749 section 5.2) deliberately does not carry the header, since it is not a bearer failure. Purely additive.</p><h3 id="identity-provider-updates-keep-attributes-they-do-not-mention" tabindex="-1">Identity provider updates keep attributes they do not mention <a class="header-anchor" href="#identity-provider-updates-keep-attributes-they-do-not-mention" aria-label="Permalink to &quot;Identity provider updates keep attributes they do not mention&quot;">​</a></h3><p><code>POST /identity-providers/:id</code> replaced the provider&#39;s whole extra-attribute set, so an update that said nothing about a key deleted it. Automation written before <code>requiredAmr</code> / <code>requiredAcr</code> existed therefore turned the upstream assurance gate off just by updating an OAuth2 provider. A partial update now keeps attributes it never mentioned. Send an attribute as <code>null</code> to clear it. Changing a provider&#39;s <code>protocol</code> still replaces the set, so the old protocol&#39;s configuration (including its secret) does not linger.</p><h3 id="the-identity-provider-assurance-gate-checks-the-id-token-audience" tabindex="-1">The identity provider assurance gate checks the id_token audience <a class="header-anchor" href="#the-identity-provider-assurance-gate-checks-the-id-token-audience" aria-label="Permalink to &quot;The identity provider assurance gate checks the id_token audience&quot;">​</a></h3><p>With <code>requiredAmr</code> or <code>requiredAcr</code> set, the upstream <code>id_token</code> must now carry the provider&#39;s <code>clientId</code> as its <strong>only</strong> audience, and an <code>azp</code>, if present, must name it too. OIDC Core section 3.1.3.7 item 3 rejects a token listing any audience the client does not trust, and authup has no trusted-audience setting, so the client&#39;s own id is the only trusted one.</p><p>Providers with neither allow-list set are unaffected, and a conformant OIDC provider issuing a token for one relying party satisfies this already. An upstream that mints one id_token for several audiences at once will start failing logins when you opt into assurance.</p><h3 id="docker-the-writable-directory-moved-to-var-lib-authup" tabindex="-1">Docker: the writable directory moved to <code>/var/lib/authup</code> <a class="header-anchor" href="#docker-the-writable-directory-moved-to-var-lib-authup" aria-label="Permalink to &quot;Docker: the writable directory moved to `/var/lib/authup`&quot;">​</a></h3><p>The image wrote its runtime files to <code>/usr/src/app/writable</code>, inside the application install directory. It now uses <code>/var/lib/authup</code>, which is where the filesystem hierarchy standard puts mutable application state and which is a cleaner mount point than a path nested in the install tree.</p><p><strong>Action required if you mount a volume at the old path.</strong> Update the mount target; the volume itself is unchanged.</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> volumes:</span></span>\n<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-  - authup:/usr/src/app/writable</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  - authup:/var/lib/authup</span></span></code></pre></div><p>The same applies to a bind-mounted provisioning directory: <code>-v /path/to/provisioning:/var/lib/authup/provisioning</code>.</p><p>Miss this and nothing fails loudly: the container starts, writes its production log files inside the container layer instead of the volume, and finds no provisioning files, so file-based provisioning silently stops being applied. Set <code>WRITABLE_DIRECTORY_PATH=/usr/src/app/writable</code> to keep the old location instead.</p><p>Only the image default changed. Running outside Docker still defaults to <code>writable</code> relative to the application root, so an unprivileged <code>npx</code> or bare-metal start is unaffected.</p><h3 id="a-relative-writabledirectorypath-now-resolves-against-rootpath" tabindex="-1">A relative <code>writableDirectoryPath</code> now resolves against <code>rootPath</code> <a class="header-anchor" href="#a-relative-writabledirectorypath-now-resolves-against-rootpath" aria-label="Permalink to &quot;A relative `writableDirectoryPath` now resolves against `rootPath`&quot;">​</a></h3><p>The documented behavior - a relative path is resolved against <code>rootPath</code> - was implemented for <code>themeDirectoryPath</code>, <code>authConsolePath</code> and <code>accountConsolePath</code> but not for <code>writableDirectoryPath</code>, which stayed relative to the process working directory and ignored <code>rootPath</code> entirely. It now resolves like its siblings.</p><p>This only changes behavior for a deployment that sets <code>rootPath</code> to something other than the working directory <strong>and</strong> gives <code>writableDirectoryPath</code> a relative value. Absolute values, and the default, are unaffected.</p><h3 id="get-identity-providers-id-now-requires-authentication" tabindex="-1"><code>GET /identity-providers/:id</code> now requires authentication <a class="header-anchor" href="#get-identity-providers-id-now-requires-authentication" aria-label="Permalink to &quot;`GET /identity-providers/:id` now requires authentication&quot;">​</a></h3><p>The endpoint was anonymous. It now requires an identity holding one of <code>IDENTITY_PROVIDER_READ</code>, <code>IDENTITY_PROVIDER_UPDATE</code> or <code>IDENTITY_PROVIDER_DELETE</code> for that provider&#39;s realm. A request without a token answers <code>401</code>; an authenticated caller lacking the permission answers <code>403</code> with code <code>permission_evaluation_failed</code>.</p><p>The record read carries the provider&#39;s extra attributes, which for an OAuth2 provider include <code>clientSecret</code> and for an LDAP provider the bind password. The previous behavior handed those to anyone who knew a provider id.</p><p><strong>Action required only if you read a single provider without a token.</strong> The collection stays anonymous, because the hosted login page lists providers before anyone signs in, and it never carries the extra attributes. Read the one provider from it instead:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /identity-providers?filter[id]=&lt;provider-id&gt;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /identity-providers?filter[name]=&lt;provider-name&gt;</span></span></code></pre></div><p>Both key forms the record route accepted are filterable, so a caller addressing a provider by name has a substitute too.</p><h2 id="v1-0-0-beta-62" tabindex="-1">v1.0.0-beta.62 <a class="header-anchor" href="#v1-0-0-beta-62" aria-label="Permalink to &quot;v1.0.0-beta.62&quot;">​</a></h2><h3 id="auth-identity-provider-accounts-gains-a-unique-constraint" tabindex="-1"><code>auth_identity_provider_accounts</code> gains a unique constraint <a class="header-anchor" href="#auth-identity-provider-accounts-gains-a-unique-constraint" aria-label="Permalink to &quot;`auth_identity_provider_accounts` gains a unique constraint&quot;">​</a></h3><p><code>(provider_id, provider_user_id)</code> becomes unique, so one external identity belongs to exactly one local user. Until now that invariant was enforced only by a read-then-write in the application, with no transaction and no row lock, so two concurrent logins or link completions for the same upstream subject could both insert. After that the subject resolved to whichever row the database happened to order first.</p><p><strong>Action required only if your deployment already holds such duplicates.</strong> The migration checks first and aborts the boot with the number of affected groups rather than a hash-named driver error. Find them with:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> provider_id, provider_user_id, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">COUNT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> auth_identity_provider_accounts</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GROUP BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> provider_id, provider_user_id</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HAVING</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> COUNT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Keep the row whose <code>user_id</code> names the account the person actually uses, and delete the rest. The unique index cannot be created while duplicates exist, so the boot would fail either way; the check only makes the reason readable.</p><h3 id="federated-login-completion-hardening" tabindex="-1">Federated login: completion hardening <a class="header-anchor" href="#federated-login-completion-hardening" aria-label="Permalink to &quot;Federated login: completion hardening&quot;">​</a></h3><ul><li>A federated login must carry the authorization code request it completes. <code>GET /identity-providers/:id/authorize-out</code> refuses a request without <code>codeRequest</code> (<code>invalid_request</code>). SDK consumers building their own login page pass it through the client: <code>client.identityProvider.getAuthorizeUri(id, { codeRequest })</code>; the bare <code>getAuthorizeUri(id)</code> URL no longer starts a login on its own.</li><li>The callback completes the request by redirecting the browser to the client&#39;s own <code>redirect_uri</code> with <code>code</code> and <code>state</code> (RFC 6749). A refusal after the callback lands on the hosted login page instead of a JSON body, and a provider answering with <code>error</code> (the user cancelled) does the same.</li><li>A custom-scheme <code>redirect_uri</code> (<code>myapp://cb</code>, RFC 8252) is served through an interstitial page that launches the app. Script-capable and local schemes (<code>javascript:</code>, <code>data:</code>, <code>vbscript:</code>, <code>blob:</code>, <code>filesystem:</code>, <code>file:</code>, <code>about:</code>) are refused everywhere: as a client redirect pattern, at <code>/authorize</code>, and at the callback.</li><li>A <code>redirectUri</code> / <code>postLogoutRedirectUri</code> pattern carrying userinfo (<code>https://user:pass@app/**</code>) is refused by the client validator, as is a <code>redirect_uri</code> carrying one at <code>/authorize</code> and <code>/logout</code>. An existing client row holding such a pattern cannot be saved again until the pattern is fixed, and a provisioning file declaring one fails the boot with the file path and the issue.</li><li>The pending-login state a federated login or an account link carries moved to its own cache namespace, so a login or link started on the previous version and completed after the upgrade is refused (<code>invalid_request</code>, up to the 30 minute state lifetime); the person starts it again. Relevant for a rolling upgrade over a shared Redis only.</li><li>The identity-provider form&#39;s read-only &quot;Redirect URL&quot; now shows the callback (<code>/identity-providers/&lt;id&gt;/authorize-in</code>), the value to register at the external provider. It used to show <code>authorize-out</code>, which is the URL that starts a login, not the one the provider redirects back to.</li><li>A substituted auth console package (<code>AUTH_CONSOLE_PATH</code>) must be built against render contract version 2, which adds the interstitial route <code>/identity-providers/:id/authorize-in</code> and its <code>IdentityProviderCallbackPayload</code>; a package exporting an older <code>CONTRACT_VERSION</code> is refused at boot.</li></ul><h2 id="v1-0-0-beta-60" tabindex="-1">v1.0.0-beta.60 <a class="header-anchor" href="#v1-0-0-beta-60" aria-label="Permalink to &quot;v1.0.0-beta.60&quot;">​</a></h2><h3 id="fixed-external-identity-provider-login" tabindex="-1">Fixed: external identity-provider login <a class="header-anchor" href="#fixed-external-identity-provider-login" aria-label="Permalink to &quot;Fixed: external identity-provider login&quot;">​</a></h3><p>The token exchange against an external OAuth2 / OIDC provider never sent the <code>code</code> parameter, so <strong>every federated login has failed since v1.0.0-beta.28</strong> with an <code>invalid_request</code> from the provider&#39;s token endpoint. The callback passed the raw code string where the authenticator expected <code>{ code }</code>, and the HTTP client spread it into indexed body keys (<code>0=d&amp;1=b&amp;...</code>). <strong>No action is required</strong> beyond upgrading. A callback that arrives without a code is now rejected with a <code>400</code> instead of an opaque upstream failure.</p><h3 id="auth-sessions-client-id-is-the-client-subject-foreign-key-only" tabindex="-1"><code>auth_sessions.client_id</code> is the client-subject foreign key only <a class="header-anchor" href="#auth-sessions-client-id-is-the-client-subject-foreign-key-only" aria-label="Permalink to &quot;`auth_sessions.client_id` is the client-subject foreign key only&quot;">​</a></h3><p>One browser session legitimately serves several applications (the hosted auth pages and the account console share the IdP origin by design), so a single column could never name all of them: it was last-writer-wins and accurate for none. Per-application attribution moved one level down, onto <code>auth_session_tokens.client_id</code>.</p><p><code>auth_sessions.client_id</code> now means what its foreign key always implied — the subject of a <strong>client</strong> session — and is <code>NULL</code> for a user&#39;s session. Nothing writes the authorizing application there anymore.</p><ul><li><strong>Runbooks that sign an identity out of one application must change</strong>: <code>DELETE /sessions?filter[clientId]=...</code> no longer matches user sessions. Use <code>DELETE /session-tokens?filter[clientId]=...</code>, which revokes that application&#39;s tokens and leaves the session alive so the others stay signed in. To sign an identity out everywhere, filter by <code>userId</code> instead.</li><li><strong>Sessions created before the upgrade keep the old value.</strong> No backfill ships, because the column is behind <code>ON DELETE CASCADE</code>: until those rows expire (session lifetime, three days by default), deleting a retired client still force-logs-out the users whose sessions recorded it. Either wait out the lifetime before deleting a client, or run <code>UPDATE auth_sessions SET client_id = NULL WHERE sub_kind &lt;&gt; &#39;client&#39;</code>.</li></ul><h3 id="schema-migration-constraint-names-mysql-column-widths-140-indexes" tabindex="-1">Schema migration: constraint names, MySQL column widths, 140 indexes <a class="header-anchor" href="#schema-migration-constraint-names-mysql-column-widths-140-indexes" aria-label="Permalink to &quot;Schema migration: constraint names, MySQL column widths, 140 indexes&quot;">​</a></h3><p>Two migrations apply. Both are safe to run on a populated database, and the round trip is verified in CI against MySQL and PostgreSQL, but the second one is not instant on a large instance. <strong>Run <code>authup migration run</code> before the rolling restart</strong> rather than letting the first pod apply it under traffic.</p><ul><li>Index, unique and foreign-key names move onto the values TypeORM derives from the entity metadata. Names have no runtime meaning; this only ends a split where two naming regimes coexisted and every generated migration emitted 32 renames before its actual change.</li><li><strong>MySQL only</strong>: 15 <code>uuid</code> columns widen from <code>varchar(36)</code> to the <code>varchar(255)</code> TypeORM derives for them. This rewrites those tables, blocks writes for the duration and needs disk headroom for the copy. It runs first and is re-runnable, so an interrupted upgrade retries cleanly.</li><li>140 indexes are added, backing the filter and sort vocabulary each entity advertises (see below) and the remaining foreign-key columns. On PostgreSQL the migrations run in one transaction, so the largest tables (<code>auth_events</code>, <code>auth_sessions</code>, <code>auth_session_tokens</code>) are locked for the duration of the build.</li><li>Three orphaned tables are <strong>dropped with their rows</strong>: <code>auth_authorization_codes</code>, <code>auth_refresh_tokens</code> and <code>auth_identity_provider_roles</code>. Each was superseded years ago (codes moved to cache blobs, refresh tokens to <code>auth_session_tokens</code>, provider roles to <code>auth_identity_provider_role_mappings</code>) and no entity has described them since. Back them up first if you still read them out of band.</li></ul><h3 id="api-meta-schema-sort-is-now-meta-schema-sorts" tabindex="-1">API: <code>meta.schema.sort</code> is now <code>meta.schema.sorts</code> <a class="header-anchor" href="#api-meta-schema-sort-is-now-meta-schema-sorts" aria-label="Permalink to &quot;API: `meta.schema.sort` is now `meta.schema.sorts`&quot;">​</a></h3><p>The query-capable <code>GET</code> endpoints describe their vocabulary under <code>meta.schema</code>. Its sort key was renamed <code>sort</code> → <code>sorts</code> (rapiq 2.1.0, which made <code>sorts</code> canonical on every developer-authored surface). <strong>A client that reads <code>meta.schema.sort</code> must follow</strong>; there is no alias. The <code>?sort=-name</code> URL parameter is unchanged.</p><p>Filters and sorts are also index-anchored now: every key an endpoint allows is backed by a real index, so single-key filters and sorts behave exactly as before. The one narrowing is a <strong>multi-key sort</strong> with no matching composite index prefix, which is now dropped whole rather than executed — the request still succeeds, unsorted.</p><h2 id="v1-0-0-beta-59" tabindex="-1">v1.0.0-beta.59 <a class="header-anchor" href="#v1-0-0-beta-59" aria-label="Permalink to &quot;v1.0.0-beta.59&quot;">​</a></h2><h3 id="security-fix-redirect-patterns-with-a-host-wildcard" tabindex="-1">Security fix: redirect patterns with a host wildcard <a class="header-anchor" href="#security-fix-redirect-patterns-with-a-host-wildcard" aria-label="Permalink to &quot;Security fix: redirect patterns with a host wildcard&quot;">​</a></h3><p>A <code>redirectUri</code> / <code>postLogoutRedirectUri</code> pattern carrying a <code>*</code> in its host (<code>https://*.example.com/**</code>) matched more than its host. The matcher treats <code>/</code> as its only boundary, while a URL authority also ends at <code>?</code>, <code>#</code> and <code>\\</code>, so <code>https://evil.test?.example.com/cb</code> matched the pattern above and an authorization code was issued to <code>evil.test</code>.</p><p>The candidate is now canonicalized before matching, so the string that gets authorized is the string the browser navigates to. <strong>No action is required</strong>, and no legitimate redirect stops matching. Three side effects are worth knowing:</p><ol><li>Both the request and the stored pattern are normalized before comparison, so a host differing only in case, an explicit default port (<code>:443</code> on https) and <code>.</code>/<code>..</code> segments resolve on either side. A path-scoped pattern can no longer be walked out of with <code>..</code>, and a pattern that was written non-canonically (<code>https://APP.example.com/**</code>, <code>https://app.example.com:443/**</code>) now matches the requests it always looked like it should.</li><li><code>**</code> is no longer accepted inside the host of a pattern. It matches the rest of the value outright, so <code>https://**.example.com/**</code> read as &quot;any subdomain&quot; but accepted every origin. A single <code>*</code> is unchanged: it matches any run of characters that does not cross a <code>/</code>, so it spans dots and <code>https://*.example.com/**</code> covers <code>https://a.b.example.com/cb</code> as well as <code>https://a.example.com/cb</code>. A stored pattern is not rewritten; only new writes are rejected.</li><li><code>TRUSTED_ORIGINS</code> rejects the same shape at startup, with a message naming the offending value.</li></ol><h3 id="client-web-was-renamed-to-client-admin-console" tabindex="-1"><code>client/web</code> was renamed to <code>client/admin-console</code> <a class="header-anchor" href="#client-web-was-renamed-to-client-admin-console" aria-label="Permalink to &quot;`client/web` was renamed to `client/admin-console`&quot;">​</a></h3><p>The rename of the admin console app (<code>@authup/client-web</code> → <code>@authup/client-admin-console</code>) reaches the operator surface. There is <strong>no backwards alias</strong>, and an unknown selector is now a hard error instead of a silent success:</p><ul><li><strong>Docker</strong>: <code>docker run authup/authup client/web start</code> → <code>client/admin-console start</code>. The entrypoint used to exit <code>0</code> on an unknown service, so this previously looked like a healthy container that started nothing. It now exits <code>1</code>.</li><li><strong>Launcher config</strong>: a <code>client.web</code> section in <code>authup.conf</code> is no longer read. Rename it to <code>client.admin-console</code>, otherwise every key in it (<code>port</code>, <code>host</code>, <code>apiUrl</code>, <code>cookieDomain</code>) silently falls back to its default.</li><li><strong>CLI</strong>: <code>authup start client/web</code> → <code>authup start client/admin-console</code>.</li><li><strong>Binary</strong>: <code>authup-ui</code> → <code>authup-admin-console</code>.</li></ul><h3 id="admin-console-and-account-console-are-reserved-client-names" tabindex="-1"><code>admin-console</code> and <code>account-console</code> are reserved client names <a class="header-anchor" href="#admin-console-and-account-console-are-reserved-client-names" aria-label="Permalink to &quot;`admin-console` and `account-console` are reserved client names&quot;">​</a></h3><p>Both names are now provisioned as system clients in every realm. If a client of either name already exists, <strong>it is taken over</strong> rather than left alone: the provisioner overwrites <code>name</code>, <code>realmId</code>, <code>authMethod</code>, <code>tokenBindingMethod</code>, <code>builtIn</code>, <code>active</code>, <code>grantTypes</code>, <code>scope</code>, <code>redirectUri</code> and <code>postLogoutRedirectUri</code>, which makes it a public (secret-less) auto-consenting client.</p><p>Rename any existing client on those names <strong>before</strong> upgrading. Attributes outside that list (<code>displayName</code>, <code>description</code>, <code>accessPolicyId</code>, junction rows) are preserved.</p><h3 id="the-per-realm-web-client-was-removed" tabindex="-1">The per-realm <code>web</code> client was removed <a class="header-anchor" href="#the-per-realm-web-client-was-removed" aria-label="Permalink to &quot;The per-realm `web` client was removed&quot;">​</a></h3><p>The shared <code>web</code> system client is no longer provisioned. Authup&#39;s own consoles were moved off it earlier (<code>admin-console</code> / <code>account-console</code>); it existed purely for downstream applications and was default-on attack surface (auto-consent + <code>global</code> scope in every realm).</p><p><strong>Existing <code>web</code> rows are not touched</strong>: logins against them keep working. Two behavior changes require action:</p><ol><li><code>PUBLIC_URL</code> / <code>TRUSTED_ORIGINS</code> changes no longer propagate to the leftover rows; their <code>redirectUri</code> / <code>postLogoutRedirectUri</code> are frozen as-is.</li><li>Realms created after the upgrade get no <code>web</code> client, so a <code>client_id=web</code> login breaks there.</li></ol><p>Register a client of your own instead. To keep the every-realm semantics, declare it once via a <a href="./provisioning.html#realm-wildcard-name">wildcard realm entry</a> (<code>realms[].attributes.name: &quot;*&quot;</code>), which also offers a declarative <code>absent</code> cleanup for the leftover <code>web</code> rows. <code>CLIENT_WEB_NAME</code> was removed from <code>@authup/core-kit</code>, and <code>web</code> is a regular, creatable client name again.</p><h2 id="v1-0-0-beta-52-was-next-release-after-v1-0-0-beta-51" tabindex="-1">v1.0.0-beta.52 (was: next release after v1.0.0-beta.51) <a class="header-anchor" href="#v1-0-0-beta-52-was-next-release-after-v1-0-0-beta-51" aria-label="Permalink to &quot;v1.0.0-beta.52 (was: next release after v1.0.0-beta.51)&quot;">​</a></h2><h3 id="login-redirect-allowlist-—-set-trusted-origins" tabindex="-1">Login redirect allowlist — set <code>TRUSTED_ORIGINS</code> <a class="header-anchor" href="#login-redirect-allowlist-—-set-trusted-origins" aria-label="Permalink to &quot;Login redirect allowlist — set `TRUSTED_ORIGINS`&quot;">​</a></h3><p>Interactive login runs through the authorization-code flow against a per-realm <code>web</code> client whose redirect allowlist is built from the origin of <code>PUBLIC_URL</code> plus every entry in <code>TRUSTED_ORIGINS</code> (renamed from <code>ADDITIONAL_DOMAINS</code>).</p><p><strong>If your web UI is served from a different origin than <code>PUBLIC_URL</code></strong> (e.g. UI on <code>https://app.example.com</code>, server on <code>https://auth.example.com</code>) <strong>you must set</strong>:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRUSTED_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.example.com</span></span></code></pre></div><p>Otherwise every login fails after the redirect with an opaque OAuth2 error. Entries may be bare hosts (expanded to both <code>http</code> and <code>https</code>) or full origins; comma-separated.</p><div class="warning custom-block"><p class="custom-block-title">Security</p><p>Each trusted origin is added to a <code>builtIn</code> (auto-consent) client carrying the <code>global</code> scope — an allowlisted origin can obtain full-permission user tokens. Only list origins you control.</p></div><h3 id="refresh-token-rotation-hard-cutover" tabindex="-1">Refresh-token rotation (hard cutover) <a class="header-anchor" href="#refresh-token-rotation-hard-cutover" aria-label="Permalink to &quot;Refresh-token rotation (hard cutover)&quot;">​</a></h3><p>Every <code>refresh_token</code> grant now rotates: the presented token is retired and a fresh pair is issued. Refresh tokens minted <strong>before</strong> the upgrade are rejected with <code>invalid_grant</code> — active users have to sign in once after the upgrade. Replaying an already-consumed refresh token revokes the whole session family (RFC 6819 §5.2.2.3). A multi-tab tolerance window can be configured via <code>TOKEN_REFRESH_GRACE_PERIOD</code> (seconds, default <code>0</code> = strict).</p><h3 id="access-token-ttl-default-lowered-3600-→-900-seconds" tabindex="-1">Access-token TTL default lowered: 3600 → 900 seconds <a class="header-anchor" href="#access-token-ttl-default-lowered-3600-→-900-seconds" aria-label="Permalink to &quot;Access-token TTL default lowered: 3600 → 900 seconds&quot;">​</a></h3><p>Shrinks the revocation blind spot for stateless JWKS-verifying adapters. Override via <code>TOKEN_ACCESS_MAX_AGE</code> (seconds) if your deployment depends on longer-lived access tokens.</p><h3 id="authorize-token-flows-are-realm-bound" tabindex="-1">Authorize &amp; token flows are realm-bound <a class="header-anchor" href="#authorize-token-flows-are-realm-bound" aria-label="Permalink to &quot;Authorize &amp; token flows are realm-bound&quot;">​</a></h3><p>An identity can only authorize (or redeem a code / refresh a token) against a client in <strong>its own realm</strong> — a cross-realm attempt yields <code>login_required</code> / <code>invalid_grant</code>. Consequences:</p><ul><li>Master-realm admins can no longer sign into other realms&#39; applications through the built-in <code>web</code> client; use an identity of the target realm.</li><li>A client identified <strong>by name</strong> at <code>/authorize</code> now requires a realm hint (<code>realm_id</code>), since every realm has a <code>web</code> client.</li></ul><h3 id="implicit-hybrid-response-types-removed" tabindex="-1">Implicit &amp; hybrid response types removed <a class="header-anchor" href="#implicit-hybrid-response-types-removed" aria-label="Permalink to &quot;Implicit &amp; hybrid response types removed&quot;">​</a></h3><p><code>response_type=code</code> is the only supported response type (OAuth 2.1 posture). Public clients must use PKCE and <code>state</code> unconditionally; the <code>id_token</code> is minted at the <code>/token</code> exchange. RPs still using <code>token</code> / <code>id_token</code> / hybrid response types must migrate to the code flow.</p><h3 id="rp-initiated-logout-discovery-corrections" tabindex="-1">RP-initiated logout &amp; discovery corrections <a class="header-anchor" href="#rp-initiated-logout-discovery-corrections" aria-label="Permalink to &quot;RP-initiated logout &amp; discovery corrections&quot;">​</a></h3><ul><li>New <code>end_session_endpoint</code>: <code>GET/POST /logout</code> (advertised in the realm discovery document). Downstream apps should end the shared authup session by redirecting there with an <code>id_token_hint</code>.</li><li><code>post_logout_redirect_uri</code> is honored only when it matches the client&#39;s <strong>new, separate</strong><code>post_logout_redirect_uri</code> column — a URI matching only the login <code>redirect_uri</code> is rejected. Set the column for clients that use post-logout redirects (the provisioned <code>web</code> client is populated automatically).</li><li>Discovery <code>revocation_endpoint</code> was corrected from <code>…/token</code> to <code>…/token/revoke</code> (RFC 7009).</li></ul><h3 id="minimum-password-length-raised-to-10" tabindex="-1">Minimum password length raised to 10 <a class="header-anchor" href="#minimum-password-length-raised-to-10" aria-label="Permalink to &quot;Minimum password length raised to 10&quot;">​</a></h3><p>New password writes (user create/update, registration, password reset) reject values shorter than 10 characters — configurable via <code>PASSWORD_MIN_LENGTH</code>. Existing password hashes keep verifying; nobody is forced to reset. File-provisioned users whose configured password is shorter than the floor now fail provisioning validation at startup.</p><h3 id="client-granttypes-is-now-enforced" tabindex="-1"><code>Client.grantTypes</code> is now enforced <a class="header-anchor" href="#client-granttypes-is-now-enforced" aria-label="Permalink to &quot;`Client.grantTypes` is now enforced&quot;">​</a></h3><p>A non-null <code>grantTypes</code> value (space- or comma-delimited) acts as an allowlist at the <code>/token</code> grants and the <code>/authorize</code> code request; violations fail with <code>unauthorized_client</code>. <code>null</code> keeps allow-all semantics, so only clients that <em>set</em> the column are affected — review clients that stored decorative values (e.g. a client listing only <code>authorization_code</code> will fail token refreshes until <code>refresh_token</code> is added). The provisioned per-realm <code>web</code> client already lists <code>authorization_code refresh_token</code>.</p><h3 id="also-notable-no-action-required" tabindex="-1">Also notable (no action required) <a class="header-anchor" href="#also-notable-no-action-required" aria-label="Permalink to &quot;Also notable (no action required)&quot;">​</a></h3><ul><li><strong>Session management</strong>: <code>GET/DELETE /sessions</code> API plus a sessions UI (&quot;This device&quot; marker, &quot;log out other devices&quot;, admin force-logout).</li><li><strong>OIDC prompt surface</strong>: <code>/authorize</code> supports <code>prompt</code> (<code>none|login|consent|select_account</code>), <code>max_age</code> and <code>login_hint</code>; the <code>@authup/client-web-kit</code> URL builder now defaults to <code>prompt=select_account</code>, so kit-based apps inherit an account chooser on lingering sessions (pass an explicit <code>prompt</code> to opt out).</li><li><strong>id_token claims</strong>: <code>auth_time</code> now reflects the real authentication instant and a <code>sid</code> (session id) claim is included.</li></ul>',130)])])}const g=o(i,[["render",r]]);export{p as __pageData,g as default};
